import org.gradle.api.artifacts.VersionCatalogsExtension

/*
 * This file was generated by the Gradle 'init' task.
 *
 * This project uses @Incubating APIs which are subject to change.
 */

plugins {
    id("jskat.kotlin-application-conventions")

    alias(libs.plugins.javafx)
}

dependencies {
    implementation(project(":jskat-gui"))
}

val javafxVersion = extensions.getByType<VersionCatalogsExtension>()
    .named("libs")
    .findVersion("javafx")
    .get()
    .requiredVersion

javafx {
    modules = listOf("javafx.base", "javafx.fxml", "javafx.web")
    version = javafxVersion
}

version = "0.24.0-SNAPSHOT"

val applicationVersion = version.toString()
val generatedVersionSourceDirectory = layout.buildDirectory.dir("generated/sources/application-version/kotlin")

val generateApplicationVersionSource by tasks.registering {
    val outputFile = generatedVersionSourceDirectory.map {
        it.file("org/jskat/ApplicationVersion.kt")
    }

    inputs.property("applicationVersion", applicationVersion)
    outputs.dir(generatedVersionSourceDirectory)

    doLast {
        outputFile.get().asFile.apply {
            parentFile.mkdirs()
            writeText(
                """
                package org.jskat

                internal object ApplicationVersion {
                    const val VALUE = "$applicationVersion"
                }
                """.trimIndent() + "\n"
            )
        }
    }
}

kotlin {
    sourceSets.named("main") {
        kotlin.srcDir(generateApplicationVersionSource)
    }
}

val mainClassName = "org.jskat.JSkatKt"

application {
    // Define the main class for the application.
    applicationName = "JSkat"
    mainClass.set(mainClassName)
}

tasks.register("fatjar", Jar::class.java) {

    manifest {
        attributes("Main-Class" to mainClassName)
    }

    duplicatesStrategy = DuplicatesStrategy.EXCLUDE

    archiveBaseName.set(rootProject.name)
    val os: OperatingSystem =
        org.gradle.nativeplatform.platform.internal.DefaultNativePlatform.getCurrentOperatingSystem()
    if (os.isLinux) {
        archiveClassifier.set("linux")
    } else if (os.isMacOsX) {
        archiveClassifier.set("macos")
    } else if (os.isWindows) {
        archiveClassifier.set("windows")
    }

    from(sourceSets.main.get().output)
    dependsOn(configurations.runtimeClasspath)
    from(
        configurations.runtimeClasspath.get()
            .onEach { println("add from dependencies : ${it.name}") }
            .map { if (it.isDirectory) it else zipTree(it) })
}
